    ensures |JoinInts(xs, sep)| == SumDigits(xs) + (|xs| - 1) * |sep|
  {
    JoinLen(seq(|xs|, i requires 0 <= i < |xs| => IntToString(xs[i])), sep);
    SumLenIntStrings(xs);
  }

